-- GenDB engine variant Q13-wrapped_tables: template q13.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  c_count,
  COUNT(*) AS custdist
FROM (
  SELECT
    c_custkey,
    COUNT(o_orderkey) AS c_count
  FROM (
    SELECT
      *
    FROM customer
  ) AS customer
  LEFT OUTER JOIN (
    SELECT
      *
    FROM orders
  ) AS orders
    ON c_custkey = o_custkey AND NOT o_comment LIKE $1
  GROUP BY
    c_custkey
) AS c_orders
GROUP BY
  c_count
ORDER BY
  custdist DESC,
  c_count DESC
